-- 0010_page_emblems.sql — PAGE EMBLEMS live in the table (owner's rule,
-- late Oct 2026). Adds pages.icon (the page's small MARK, master media
-- pattern — same jsonb shape as wikis.icon: {"kind":"glyph","name":…} |
-- {"kind":"art","src":…}) and SEEDS every emblem scanned off the live
-- site's WIKI_TOC pageLogo blocks (generated by
-- _builder/scripts/gen-page-emblems-sql.mjs — re-run it after a mark
-- changes page-side). Also lifts each flagship's hand-drawn wikiLogo into
-- wikis.icon where the wiki still wears the auto letter default.
-- Idempotent: re-runs refresh the icons only.
-- NOTE: the 5 iPod pages share one 84KB photo PNG as their mark — too heavy
-- for an inline seed; they stay page-side until Storage uploads land.

alter table public.pages add column if not exists icon jsonb;

-- ── the scanned PAGE emblems (upsert; stub rows carry just identity + mark —
-- they hold no published revision, so readers never see them as pages) ──
insert into public.pages (wiki_id, id, slug, title, type, icon) values
  ('taco-bell', 'taco-bell-discontinued-drinks', 'taco-bell-discontinued-drinks.html', 'Discontinued Drinks — Taco Bell', 'standard', '{"kind":"art","src":"data:image/svg+xml;base64,"}'::jsonb),
  ('taco-bell', 'taco-bell-drinks', 'taco-bell-drinks.html', 'Taco Bell Drinks — Baja Blast & The Freezer Wall · ViziWiki', 'standard', '{"kind":"art","src":"data:image/svg+xml;base64,"}'::jsonb),
  ('taco-bell', 'taco-bell-menus', 'taco-bell-menus.html', 'Taco Bell Menus — Historical & Active · ViziWiki', 'standard', '{"kind":"art","src":"data:image/svg+xml;base64,"}'::jsonb),
  ('taco-bell', 'taco-bell-sauces', 'taco-bell-sauces.html', 'Taco Bell Sauces — ViziWiki', 'standard', '{"kind":"art","src":"data:image/svg+xml;base64,PHN2ZyB2aWV3Qm94PSIwIDAgMzIgMzIiIHhtbG5zPSJodHRwOi8vd3d3LnczLm9yZy8yMDAwL3N2ZyI+"}'::jsonb),
  ('taco-bell', 'taco-bell-slogans', 'taco-bell-slogans.html', 'Taco Bell Slogans — Through the Ages · ViziWiki', 'standard', '{"kind":"art","src":"data:image/svg+xml;base64,"}'::jsonb),
  ('taco-bell', 'taco-bell-home', 'taco-bell.html', 'Taco Bell — Visual Wiki · ViziWiki', 'home', '{"kind":"art","src":"data:image/svg+xml;base64,PHN2ZyB2aWV3Qm94PSIwIDAgMzIgMzIiIHhtbG5zPSJodHRwOi8vd3d3LnczLm9yZy8yMDAwL3N2ZyI+"}'::jsonb),
  ('taco-bell', 'taco-bell-brisk-raspberry', 'taco-bell-brisk-raspberry.html', 'Brisk Raspberry Iced Tea — ViziWiki', 'standard', '{"kind":"art","src":"data:image/svg+xml;base64,"}'::jsonb),
  ('taco-bell', 'taco-bell-pina-colada-frutista', 'taco-bell-pina-colada-frutista.html', 'Piña Colada Frutista Freeze — ViziWiki', 'standard', '{"kind":"art","src":"data:image/svg+xml;base64,"}'::jsonb),
  ('taco-bell', 'taco-bell-sangrita-blast', 'taco-bell-sangrita-blast.html', 'Mtn Dew Sangrita Blast — ViziWiki', 'standard', '{"kind":"art","src":"data:image/svg+xml;base64,"}'::jsonb),
  ('taco-bell', 'taco-bell-spiked-lemonade', 'taco-bell-spiked-lemonade.html', 'Mtn Dew Spiked Lemonade — ViziWiki', 'standard', '{"kind":"art","src":"data:image/svg+xml;base64,"}'::jsonb),
  ('taco-bell', 'taco-bell-menu-2-dollar-deals', 'taco-bell-menu-2-dollar-deals.html', '$2 Meal Deals · Taco Bell · ViziWiki', 'standard', '{"kind":"art","src":"data:image/svg+xml;base64,"}'::jsonb),
  ('taco-bell', 'taco-bell-menu-big-bell-value', 'taco-bell-menu-big-bell-value.html', 'Big Bell Value Menu · Taco Bell · ViziWiki', 'standard', '{"kind":"art","src":"data:image/svg+xml;base64,"}'::jsonb),
  ('taco-bell', 'taco-bell-menu-cantina-chicken', 'taco-bell-menu-cantina-chicken.html', 'Cantina Chicken Menu · Taco Bell · ViziWiki', 'standard', '{"kind":"art","src":"data:image/svg+xml;base64,"}'::jsonb),
  ('taco-bell', 'taco-bell-menu-fresco', 'taco-bell-menu-fresco.html', 'Fresco Menu · Taco Bell · ViziWiki', 'standard', '{"kind":"art","src":"data:image/svg+xml;base64,"}'::jsonb),
  ('taco-bell', 'taco-bell-menu-luxe-value', 'taco-bell-menu-luxe-value.html', 'Luxe Value Menu · Taco Bell · ViziWiki', 'standard', '{"kind":"art","src":"data:image/svg+xml;base64,"}'::jsonb),
  ('apple', 'apple-home', 'apple.html', 'Apple', 'home', '{"kind":"art","src":"data:image/svg+xml;base64,"}'::jsonb),
  ('fallout', 'fallout-home', 'fallout.html', 'Fallout', 'home', '{"kind":"art","src":"data:image/svg+xml;base64,"}'::jsonb),
  ('smurfs-village', 'smurfs-village-home', 'smurfs-village.html', 'Smurfs'' Village', 'home', '{"kind":"art","src":"data:image/svg+xml;base64,"}'::jsonb),
