on conflict (wiki_id, id) do update set icon = excluded.icon;

-- ── the flagship WIKI emblems (hand-drawn wikiLogo marks) — fill only where
-- the wiki still wears the auto default, never clobber an owner-set mark ──
update public.wikis set icon = '{"kind":"art","src":"data:image/svg+xml;base64,PHN2ZyB2aWV3Qm94PSIwIDAgMzIgMzIiIHhtbG5zPSJodHRwOi8vd3d3LnczLm9yZy8yMDAwL3N2ZyI+"}'::jsonb
  where id = 'taco-bell' and (icon is null or icon->>'kind' = 'auto');
update public.wikis set icon = '{"kind":"art","src":"data:image/svg+xml;base64,"}'::jsonb
  where id = 'apple' and (icon is null or icon->>'kind' = 'auto');
update public.wikis set icon = '{"kind":"art","src":"data:image/svg+xml;base64,"}'::jsonb
  where id = 'fallout' and (icon is null or icon->>'kind' = 'auto');
update public.wikis set icon = '{"kind":"art","src":"data:image/svg+xml;base64,"}'::jsonb
  where id = 'smurfs-village' and (icon is null or icon->>'kind' = 'auto');
update public.wikis set icon = '{"kind":"art","src":"data:image/svg+xml;base64,"}'::jsonb
  where id = 'doodle-jump' and (icon is null or icon->>'kind' = 'auto');
